using Godot;
using System;
using System.Linq;
public partial class MigrationScene {
 static bool IsSettlementActor(string id)=>id.StartsWith("settler/")||id.StartsWith("ledger-raider/");
 static bool IsSettlementMission(string id)=>id.StartsWith("settlement-mission/");
 bool SettlementAtWar(int i)=>i==3?Ledger.State=="enemy":Ledger.Target==i&&Ledger.State is "assault" or "burning";
 bool SettlementPeaceful(string id)=>id.StartsWith("settler/")&&!SettlementAtWar(int.Parse(id.Split('/')[1]));
 bool SettlementArmed(string id)=>!id.StartsWith("settler/")||id.Split('/')[2]=="2"||Town(int.Parse(id.Split('/')[1])).Foundation=="fortify";
 void SettlementFighterArt(Node3D root,string id){HumanCharacter(root,1,0,true);var weapon=new Node3D{Scale=Vector3.One*.55f,RotationDegrees=new(-45,0,0)};root.GetNode<Node3D>("RightArm/Elbow/Hand").AddChild(weapon);ItemWeapon(weapon,SettlementArmed(id)?0:13,false);if(id.StartsWith("ledger-raider/"))Box(root.GetNode<Node3D>("Torso"),new(0,.25f,-.16f),new(.16f,.2f,.04f),new(.55f,.08f,.07f));}
 void SpawnSettlementCombatants(int index){if(index<0||Town(index)==null||Town(index).Fallen)return;var t=Town(index);if(!NearActiveSurface(Ground(t.X,t.Z),130))return;for(int j=0;j<4;j++){if((t.DeadResidents&(1<<j))!=0)continue;AddEnemy($"settler/{index}/{j}/{game.Save.Seed}",t.X+(j-1.5)*2,t.Z+2,index==3?4:2);}}
 bool TickSettlementActor(Infected e,double dt){if(!IsSettlementActor(e.Id))return false;if(e.Id.StartsWith("settler/")){int i=int.Parse(e.Id.Split('/')[1]),j=int.Parse(e.Id.Split('/')[2]);if((Town(i).DeadResidents&(1<<j))!=0||Town(i).Fallen){RemoveLivingActor(e);return true;}if(!SettlementAtWar(i))return true;}return TickSettlementFighter(e,dt);}
 bool TickSettlementFighter(Infected e,double dt){if(FieldStunned(e))return true;e.Memory=8;e.Stagger=Math.Max(0,e.Stagger-dt);e.Cooldown=Math.Max(0,e.Cooldown-dt);bool armed=SettlementArmed(e.Id);bool raider=e.Id.StartsWith("ledger-raider/");Vector3 target=player.Position;CampSurvivor npc=null;bool dog=false;float distance=Distance(e.Body.Position,target);
  if(raider){npc=ZombieCommunityTarget(e,distance);if(npc!=null){target=NpcPoint(npc);distance=Distance(e.Body.Position,target);}dog=DogCanBeTarget(e,distance);if(dog){npc=null;target=DogPoint;distance=Distance(e.Body.Position,target);}}
  bool sight=!FieldSmoke(e.Body.Position+Vector3.Up,target+Vector3.Up)&&distance<(armed?32:2)&&PursuitClear(e.Body.Position,target,PursuitExclusions());e.Target=target;var direction=target-e.Body.Position;direction.Y=0;if(direction.LengthSquared()>.01)e.Body.Rotation=new(0,Mathf.Atan2(-direction.X,-direction.Z),0);
  if(e.Stagger>0)e.AttackState="";else if(e.AttackState=="human-aim"){e.AttackTime-=dt;if(e.AttackTime<=0){if(sight){if(dog)HurtRescueDog(armed?18:12);else if(npc!=null)HurtCommunity(npc,armed?16:10);else MillDamage(game,player,armed?14:10,false);if(armed){CheckpointGunshot(e.Body.Position);CommunityTracer(e.Body.Position+Vector3.Up*1.3f,target+Vector3.Up*.8f);}}e.AttackState="";e.Cooldown=armed?1.8:1.2;}}
  else if(e.Cooldown<=0&&sight){e.AttackState="human-aim";e.AttackTime=.85;}
  Vector3 goal=raider&&distance>28?Ground(Ledger.RaidX,Ledger.RaidZ):target;var move=e.Stagger<=0&&e.AttackState==""&&(!sight||!armed)?PursuitDirection(e,goal,dt):Vector3.Zero;var velocity=move.Length()>1.2?move.Normalized()*3:Vector3.Zero;velocity.Y=e.Body.IsOnFloor()?-.1f:e.Body.Velocity.Y-18*(float)dt;e.Body.Velocity=velocity;e.Body.MoveAndSlide();PoseFigure(e.Visual,(float)game.Clock*5,velocity.Length()>1?1:0,false);if(e.AttackState=="human-aim")foreach(string side in new[]{"Left","Right"})e.Visual.GetNode<Node3D>(side+"Arm").RotationDegrees=new(-85,0,0);if(raider)DamageBaseNear(e);
  if(Ledger.Burning&&e.Id.StartsWith("settler/"+Ledger.Target+"/")&&Distance(e.Body.Position,Ground(Town(Ledger.Target).X,Town(Ledger.Target).Z))<24){e.Hp-=dt*7;if(e.Hp<=0)SettlementCombatDeath(e);}return true;
 }
 bool SettlementCombatDeath(Infected e){if(IsSettlementMission(e.Id)){var bits=e.Id.Split('/');var t=Town(int.Parse(bits[1]));t.MissionKills|=1<<int.Parse(bits[2]);game.Skills.Defeated.Add(e.Id);game.Career.Gain(16);RemoveLivingActor(e);game.Persist();return true;}
  if(e.Id.StartsWith("ledger-raider/")){Ledger.DefeatedRaiders|=1<<int.Parse(e.Id.Split('/')[1]);game.Skills.Defeated.Add(e.Id);DeathRemains(e);RemoveLivingActor(e);if((Ledger.DefeatedRaiders&15)==15){Ledger.RaidOver=true;Ledger.Outcome="You repelled the Black Ledger's retaliation. Damage and injuries remain; their city market stays hostile.";game.WorldDecision("ledger/raid-defended",Ledger.Outcome);}game.Persist();return true;}
  int index,person;if(e.Id.StartsWith("settler/")){var bits=e.Id.Split('/');index=int.Parse(bits[1]);person=int.Parse(bits[2]);}else if(IsTownGuard(e.Id)){index=int.Parse(e.Id.Split('/')[2]);person=4;if(!SettlementAtWar(index))return false;}else return false;
  var town=Town(index);town.DeadResidents|=1<<person;DeathRemains(e);game.Skills.Defeated.Add(e.Id);RemoveLivingActor(e);RememberTown(index,-25,person==4?"You killed our guard.":"You killed "+ResidentNames[index][person]+".");
  if((town.DeadResidents&31)==31){town.Fallen=town.Destroyed=true;town.Trust=-100;town.Development=0;town.StoryResult="All four adult residents and their guard are dead. The settlement and its trade are gone permanently.";if(index==Ledger.Target&&Ledger.State is "assault" or "burning"){Ledger.State="completed";Ledger.Due=0;Town(3).Development=3;Town(3).Trust=60;RememberTown(3,40,"Voss approved the destruction of "+ExpeditionGame.SettlementNames[index]);Ledger.Outcome="Voss opens the highest city stock. The settlement you destroyed will never trade again. Your former allies remember who did this.";foreach(var other in game.World.Changes.Settlements.Where(t=>t.Index<3&&t.Index!=index))RememberTown(other.Index,-30,"Word reached us about the settlement you erased.");game.World.Changes.Remember(CommunityOwner,"home",-30,"We heard what you did to the settlement.");foreach(var resident in Community.Survivors.Where(n=>n.Member)){game.World.Changes.Remember(CommunityOwner,resident.Id,-40,"You erased people who once trusted us. I need distance from you.");if(resident.Owner==CommunityOwner&&Standing(resident.Id).Value<0)resident.Owner="";}game.Life.Morale=Math.Max(0,game.Life.Morale-30);game.WorldDecision("ledger/extermination",Ledger.Outcome);}game.WorldDecision("settlement/destroyed/"+index,town.StoryResult);}
  game.Persist();return true;
 }
 bool LocateLedgerCamp(){if(Ledger.RaidLocated)return true;if(Community.Established){Ledger.RaidX=Community.X;Ledger.RaidZ=Community.Z;}else{var bag=game.Life.Camps.FirstOrDefault(b=>b.Seed==game.Save.Seed);var piece=game.Building.Pieces.FirstOrDefault();if(bag==null&&piece==null)return false;Ledger.RaidX=bag?.X??piece.X;Ledger.RaidZ=bag?.Z??piece.Z;}Ledger.RaidLocated=true;return true;}
 void TickLedgerRaid(double dt){if(!Ledger.RaidScheduled||Ledger.RaidOver||game.World.Changes.Time<Ledger.RaidDue)return;
  if(!Ledger.RaidStarted){if(!LocateLedgerCamp()||!NearActiveSurface(Ground(Ledger.RaidX,Ledger.RaidZ),120))return;Ledger.RaidStarted=true;game.Notice="BLACK LEDGER RAID / four armed survivors are approaching your camp!";game.Persist();}
  if(!NearActiveSurface(Ground(Ledger.RaidX,Ledger.RaidZ),150))return;Ledger.RaidTime+=dt;
  for(int j=0;j<4;j++){if((Ledger.DefeatedRaiders&(1<<j))!=0)continue;double a=j*1.6;var at=Ground(Ledger.RaidX+Math.Sin(a)*32,Ledger.RaidZ+Math.Cos(a)*32);string id=$"ledger-raider/{j}/{game.Save.Seed}";AddEnemy(id,at.X,at.Z,4);}
  if(Ledger.RaidTime>=300){Ledger.RaidOver=true;bool breached=(dogPackSource??infected).Any(e=>e.Id.StartsWith("ledger-raider/")&&Distance(e.Body.Position,Ground(Ledger.RaidX,Ledger.RaidZ))<12&&PursuitClear(e.Body.Position,Ground(Ledger.RaidX,Ledger.RaidZ),PursuitExclusions()));if(breached){Community.Food=Math.Max(0,Community.Food-8);Community.Water=Math.Max(0,Community.Water-8);foreach(var n in Community.Survivors.Where(n=>n.Member&&ExpeditionGame.Distance(n.X,n.Z,Ledger.RaidX,Ledger.RaidZ)<35)){n.Injury=Math.Min(100,n.Injury+35);n.Morale=Math.Max(0,n.Morale-20);}foreach(var b in game.Building.Pieces.Where(b=>ExpeditionGame.Distance(b.X,b.Z,Ledger.RaidX,Ledger.RaidZ)<30)){if(b.Stock?.Length>8){b.Stock[7]=Math.Max(0,b.Stock[7]-5);b.Stock[8]=Math.Max(0,b.Stock[8]-5);}}Ledger.Outcome="The raiders overran the camp, stole food and water, and withdrew. Residents need care; damaged buildings stay damaged.";}else Ledger.Outcome="Your perimeter held. The surviving raiders withdrew without reaching the stores. Building damage remains; the Ledger still refuses trade.";foreach(var raider in (dogPackSource??infected).Where(e=>e.Id.StartsWith("ledger-raider/")).ToArray())RemoveLivingActor(raider);game.WorldDecision(breached?"ledger/raid-overrun":"ledger/raid-held",Ledger.Outcome);game.Persist();}
 }
}
